-- 合成獸零件 v2：9 個部位 × 9 種造型，共 81 個
-- 要改零件請改 scripts/parts/parts.py，再執行一次輸出這個檔
-- 可以重複執行：先依 name UPDATE，沒有這個名字才 INSERT，不會 DELETE（user_parts 有外鍵）
-- 要先跑過 add-part-slots.sql
SET NAMES utf8mb4;
USE bug_clinic;

-- body：圓滾滾
UPDATE parts SET category = 'css', slot = 'body', price = 20, starter_code = '{"html": "", "css": ".body {\\n  border-radius: 50%;\\n}", "js": ""}' WHERE name = '圓滾滾';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '圓滾滾', 'css', 'body', 20, 'body.svg', '{"html": "", "css": ".body {\\n  border-radius: 50%;\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '圓滾滾');

