-- body：雲朵
UPDATE parts SET category = 'css', slot = 'body', price = 40, starter_code = '{"html": "", "css": "/* 頭上兩顆圓凸起，下緣不畫框、壓在身體的上框上，看起來就跟身體連在一起 */\\n.body {\\n  border-radius: 50px;\\n}\\n\\n.body::before,\\n.body::after {\\n  content: \'\';\\n  position: absolute;\\n  background: var(--fur-color);\\n  border: 4px solid #4a3426;\\n  border-bottom-color: transparent;\\n  border-radius: 50%;\\n}\\n\\n.body::before {\\n  top: -54px;\\n  left: 16px;\\n  width: 50px;\\n  height: 50px;\\n}\\n\\n.body::after {\\n  top: -64px;\\n  right: 14px;\\n  width: 60px;\\n  height: 60px;\\n}", "js": ""}' WHERE name = '雲朵';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '雲朵', 'css', 'body', 40, 'body.svg', '{"html": "", "css": "/* 頭上兩顆圓凸起，下緣不畫框、壓在身體的上框上，看起來就跟身體連在一起 */\\n.body {\\n  border-radius: 50px;\\n}\\n\\n.body::before,\\n.body::after {\\n  content: \'\';\\n  position: absolute;\\n  background: var(--fur-color);\\n  border: 4px solid #4a3426;\\n  border-bottom-color: transparent;\\n  border-radius: 50%;\\n}\\n\\n.body::before {\\n  top: -54px;\\n  left: 16px;\\n  width: 50px;\\n  height: 50px;\\n}\\n\\n.body::after {\\n  top: -64px;\\n  right: 14px;\\n  width: 60px;\\n  height: 60px;\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '雲朵');

-- body：會呼吸的身體
UPDATE parts SET category = 'css', slot = 'body', price = 40, starter_code = '{"html": "", "css": "/* 待機的時候一直慢慢呼吸，不用 JS 觸發 */\\n/* 放在外層的 .chimera：點一下跳是放在 .body，兩個動畫在不同元素上，不會互相蓋掉 */\\n/* 用 scale 不用 transform，商店小預覽縮小 .chimera 用的是 transform，兩個會疊在一起 */\\n/* 改 2.4s 調呼吸快慢，改 1.06 調放大多少 */\\n.chimera {\\n  animation: body-breathe 2.4s ease-in-out infinite;\\n}\\n\\n@keyframes body-breathe {\\n  50% {\\n    scale: 1.06;\\n  }\\n}", "js": ""}' WHERE name = '會呼吸的身體';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '會呼吸的身體', 'css', 'body', 40, 'body.svg', '{"html": "", "css": "/* 待機的時候一直慢慢呼吸，不用 JS 觸發 */\\n/* 放在外層的 .chimera：點一下跳是放在 .body，兩個動畫在不同元素上，不會互相蓋掉 */\\n/* 用 scale 不用 transform，商店小預覽縮小 .chimera 用的是 transform，兩個會疊在一起 */\\n/* 改 2.4s 調呼吸快慢，改 1.06 調放大多少 */\\n.chimera {\\n  animation: body-breathe 2.4s ease-in-out infinite;\\n}\\n\\n@keyframes body-breathe {\\n  50% {\\n    scale: 1.06;\\n  }\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '會呼吸的身體');

-- body：會變形的身體
UPDATE parts SET category = 'js', slot = 'body', price = 60, starter_code = '{"html": "", "css": ".body {\\n  cursor: pointer;\\n  transition: border-radius 0.3s;\\n}\\n\\n/* 每個形狀一個 class，想加形狀就多寫一個 .shape-4，JS 那邊的 4 也要改成 5 */\\n.body.shape-1 {\\n  border-radius: 50%;\\n}\\n\\n.body.shape-2 {\\n  border-radius: 60px 60px 8px 8px;\\n}\\n\\n.body.shape-3 {\\n  border-radius: 50% 50% 50% 50% / 60% 60% 40% 40%;\\n}", "js": "// 點身體輪流換形狀：形狀寫在 CSS 的 .shape-1 ~ .shape-3，JS 只負責換 class\\nconst morphBody = document.querySelector(\'.body\')\\nlet morphIndex = 0\\nmorphBody.addEventListener(\'click\', () => {\\n  morphBody.classList.remove(`shape-${morphIndex}`)\\n  morphIndex = (morphIndex + 1) % 4\\n  if (morphIndex) morphBody.classList.add(`shape-${morphIndex}`)\\n})"}' WHERE name = '會變形的身體';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '會變形的身體', 'js', 'body', 60, 'body.svg', '{"html": "", "css": ".body {\\n  cursor: pointer;\\n  transition: border-radius 0.3s;\\n}\\n\\n/* 每個形狀一個 class，想加形狀就多寫一個 .shape-4，JS 那邊的 4 也要改成 5 */\\n.body.shape-1 {\\n  border-radius: 50%;\\n}\\n\\n.body.shape-2 {\\n  border-radius: 60px 60px 8px 8px;\\n}\\n\\n.body.shape-3 {\\n  border-radius: 50% 50% 50% 50% / 60% 60% 40% 40%;\\n}", "js": "// 點身體輪流換形狀：形狀寫在 CSS 的 .shape-1 ~ .shape-3，JS 只負責換 class\\nconst morphBody = document.querySelector(\'.body\')\\nlet morphIndex = 0\\nmorphBody.addEventListener(\'click\', () => {\\n  morphBody.classList.remove(`shape-${morphIndex}`)\\n  morphIndex = (morphIndex + 1) % 4\\n  if (morphIndex) morphBody.classList.add(`shape-${morphIndex}`)\\n})"}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '會變形的身體');

