-- horn：鹿角
UPDATE parts SET category = 'html', slot = 'horn', price = 25, starter_code = '{"html": "<div class=\\"horn-deer left\\">\\n  <span class=\\"horn-deer-branch\\"></span>\\n</div>\\n<div class=\\"horn-deer right\\">\\n  <span class=\\"horn-deer-branch\\"></span>\\n</div>", "css": "/* 一根直的主幹，加一根橫的分岔，分岔尾端再往上長一小段 */\\n.horn-deer {\\n  position: absolute;\\n  top: calc(50% - 92px);\\n  width: 6px;\\n  height: 40px;\\n  background: #8a5a3b;\\n}\\n\\n.horn-deer.left {\\n  left: calc(50% - 34px);\\n}\\n\\n.horn-deer.right {\\n  left: calc(50% + 28px);\\n}\\n\\n.horn-deer-branch {\\n  position: absolute;\\n  top: 12px;\\n  width: 16px;\\n  height: 6px;\\n  background: #8a5a3b;\\n}\\n\\n.horn-deer.left .horn-deer-branch {\\n  left: -16px;\\n}\\n\\n.horn-deer.right .horn-deer-branch {\\n  left: 6px;\\n}\\n\\n.horn-deer-branch::after {\\n  content: \'\';\\n  position: absolute;\\n  top: -12px;\\n  width: 6px;\\n  height: 12px;\\n  background: #8a5a3b;\\n}\\n\\n.horn-deer.left .horn-deer-branch::after {\\n  left: 0;\\n}\\n\\n.horn-deer.right .horn-deer-branch::after {\\n  right: 0;\\n}", "js": ""}' WHERE name = '鹿角';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '鹿角', 'html', 'horn', 25, 'horn.svg', '{"html": "<div class=\\"horn-deer left\\">\\n  <span class=\\"horn-deer-branch\\"></span>\\n</div>\\n<div class=\\"horn-deer right\\">\\n  <span class=\\"horn-deer-branch\\"></span>\\n</div>", "css": "/* 一根直的主幹，加一根橫的分岔，分岔尾端再往上長一小段 */\\n.horn-deer {\\n  position: absolute;\\n  top: calc(50% - 92px);\\n  width: 6px;\\n  height: 40px;\\n  background: #8a5a3b;\\n}\\n\\n.horn-deer.left {\\n  left: calc(50% - 34px);\\n}\\n\\n.horn-deer.right {\\n  left: calc(50% + 28px);\\n}\\n\\n.horn-deer-branch {\\n  position: absolute;\\n  top: 12px;\\n  width: 16px;\\n  height: 6px;\\n  background: #8a5a3b;\\n}\\n\\n.horn-deer.left .horn-deer-branch {\\n  left: -16px;\\n}\\n\\n.horn-deer.right .horn-deer-branch {\\n  left: 6px;\\n}\\n\\n.horn-deer-branch::after {\\n  content: \'\';\\n  position: absolute;\\n  top: -12px;\\n  width: 6px;\\n  height: 12px;\\n  background: #8a5a3b;\\n}\\n\\n.horn-deer.left .horn-deer-branch::after {\\n  left: 0;\\n}\\n\\n.horn-deer.right .horn-deer-branch::after {\\n  right: 0;\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '鹿角');

