-- horn：會變色的角
UPDATE parts SET category = 'js', slot = 'horn', price = 50, starter_code = '{"html": "<div class=\\"horn-color\\"></div>", "css": ".horn-color {\\n  --horn-color: #f3ead8;\\n  position: absolute;\\n  top: calc(50% - 82px);\\n  left: calc(50% - 14px);\\n  border-left: 14px solid transparent;\\n  border-right: 14px solid transparent;\\n  border-bottom: 32px solid var(--horn-color);\\n  cursor: pointer;\\n  transition: border-color 0.3s;\\n}", "js": "// 點角換一個隨機顏色\\nconst colorHorn = document.querySelector(\'.horn-color\')\\ncolorHorn.addEventListener(\'click\', (event) => {\\n  // 角長在身體裡，不擋住的話也會觸發身體的點擊\\n  event.stopPropagation()\\n  const hue = Math.floor(Math.random() * 360)\\n  colorHorn.style.setProperty(\'--horn-color\', `hsl(${hue}, 70%, 65%)`)\\n})"}' WHERE name = '會變色的角';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '會變色的角', 'js', 'horn', 50, 'horn.svg', '{"html": "<div class=\\"horn-color\\"></div>", "css": ".horn-color {\\n  --horn-color: #f3ead8;\\n  position: absolute;\\n  top: calc(50% - 82px);\\n  left: calc(50% - 14px);\\n  border-left: 14px solid transparent;\\n  border-right: 14px solid transparent;\\n  border-bottom: 32px solid var(--horn-color);\\n  cursor: pointer;\\n  transition: border-color 0.3s;\\n}", "js": "// 點角換一個隨機顏色\\nconst colorHorn = document.querySelector(\'.horn-color\')\\ncolorHorn.addEventListener(\'click\', (event) => {\\n  // 角長在身體裡，不擋住的話也會觸發身體的點擊\\n  event.stopPropagation()\\n  const hue = Math.floor(Math.random() * 360)\\n  colorHorn.style.setProperty(\'--horn-color\', `hsl(${hue}, 70%, 65%)`)\\n})"}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '會變色的角');

