-- eyes：會眨眼
UPDATE parts SET category = 'css', slot = 'eyes', price = 30, starter_code = '{"html": "<div class=\\"eye-blink left\\"></div>\\n<div class=\\"eye-blink right\\"></div>", "css": "/* 大部分時間睜開，96% 那一下壓扁就是眨眼 */\\n.eye-blink {\\n  position: absolute;\\n  top: calc(50% - 20px);\\n  width: 14px;\\n  height: 14px;\\n  background: #2b1d14;\\n  animation: eye-blink 3s infinite;\\n}\\n\\n.eye-blink.left {\\n  left: calc(50% - 32px);\\n}\\n\\n.eye-blink.right {\\n  left: calc(50% + 18px);\\n}\\n\\n@keyframes eye-blink {\\n  0%,\\n  92%,\\n  100% {\\n    transform: scaleY(1);\\n  }\\n  96% {\\n    transform: scaleY(0.1);\\n  }\\n}", "js": ""}' WHERE name = '會眨眼';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '會眨眼', 'css', 'eyes', 30, 'eyes.svg', '{"html": "<div class=\\"eye-blink left\\"></div>\\n<div class=\\"eye-blink right\\"></div>", "css": "/* 大部分時間睜開，96% 那一下壓扁就是眨眼 */\\n.eye-blink {\\n  position: absolute;\\n  top: calc(50% - 20px);\\n  width: 14px;\\n  height: 14px;\\n  background: #2b1d14;\\n  animation: eye-blink 3s infinite;\\n}\\n\\n.eye-blink.left {\\n  left: calc(50% - 32px);\\n}\\n\\n.eye-blink.right {\\n  left: calc(50% + 18px);\\n}\\n\\n@keyframes eye-blink {\\n  0%,\\n  92%,\\n  100% {\\n    transform: scaleY(1);\\n  }\\n  96% {\\n    transform: scaleY(0.1);\\n  }\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '會眨眼');

-- eyes：跟著滑鼠的眼睛
UPDATE parts SET category = 'js', slot = 'eyes', price = 70, starter_code = '{"html": "<div class=\\"eye-follow left\\"><span class=\\"eye-follow-pupil\\"></span></div>\\n<div class=\\"eye-follow right\\"><span class=\\"eye-follow-pupil\\"></span></div>", "css": ".eye-follow {\\n  position: absolute;\\n  top: calc(50% - 28px);\\n  width: 24px;\\n  height: 24px;\\n  background: #ffffff;\\n  border: 3px solid #4a3426;\\n  border-radius: 50%;\\n}\\n\\n.eye-follow.left {\\n  left: calc(50% - 38px);\\n}\\n\\n.eye-follow.right {\\n  left: calc(50% + 8px);\\n}\\n\\n.eye-follow-pupil {\\n  position: absolute;\\n  top: 7px;\\n  left: 7px;\\n  width: 10px;\\n  height: 10px;\\n  background: #2b1d14;\\n  border-radius: 50%;\\n}", "js": "// 算出滑鼠在眼睛的哪個方向，眼珠往那邊移 6px\\nconst followEyes = document.querySelectorAll(\'.eye-follow\')\\ndocument.addEventListener(\'mousemove\', (e) => {\\n  followEyes.forEach((eye) => {\\n    const rect = eye.getBoundingClientRect()\\n    const angle = Math.atan2(\\n      e.clientY - (rect.top + rect.height / 2),\\n      e.clientX - (rect.left + rect.width / 2),\\n    )\\n    const pupil = eye.querySelector(\'.eye-follow-pupil\')\\n    pupil.style.transform = `translate(${Math.cos(angle) * 6}px, ${Math.sin(angle) * 6}px)`\\n  })\\n})"}' WHERE name = '跟著滑鼠的眼睛';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '跟著滑鼠的眼睛', 'js', 'eyes', 70, 'eyes.svg', '{"html": "<div class=\\"eye-follow left\\"><span class=\\"eye-follow-pupil\\"></span></div>\\n<div class=\\"eye-follow right\\"><span class=\\"eye-follow-pupil\\"></span></div>", "css": ".eye-follow {\\n  position: absolute;\\n  top: calc(50% - 28px);\\n  width: 24px;\\n  height: 24px;\\n  background: #ffffff;\\n  border: 3px solid #4a3426;\\n  border-radius: 50%;\\n}\\n\\n.eye-follow.left {\\n  left: calc(50% - 38px);\\n}\\n\\n.eye-follow.right {\\n  left: calc(50% + 8px);\\n}\\n\\n.eye-follow-pupil {\\n  position: absolute;\\n  top: 7px;\\n  left: 7px;\\n  width: 10px;\\n  height: 10px;\\n  background: #2b1d14;\\n  border-radius: 50%;\\n}", "js": "// 算出滑鼠在眼睛的哪個方向，眼珠往那邊移 6px\\nconst followEyes = document.querySelectorAll(\'.eye-follow\')\\ndocument.addEventListener(\'mousemove\', (e) => {\\n  followEyes.forEach((eye) => {\\n    const rect = eye.getBoundingClientRect()\\n    const angle = Math.atan2(\\n      e.clientY - (rect.top + rect.height / 2),\\n      e.clientX - (rect.left + rect.width / 2),\\n    )\\n    const pupil = eye.querySelector(\'.eye-follow-pupil\')\\n    pupil.style.transform = `translate(${Math.cos(angle) * 6}px, ${Math.sin(angle) * 6}px)`\\n  })\\n})"}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '跟著滑鼠的眼睛');

