-- mouth：會說話的嘴
UPDATE parts SET category = 'js', slot = 'mouth', price = 60, starter_code = '{"html": "<div class=\\"mouth-talk\\"></div>\\n<div class=\\"mouth-bubble\\"></div>", "css": ".body {\\n  cursor: pointer;\\n}\\n\\n.mouth-talk {\\n  position: absolute;\\n  top: calc(50% + 14px);\\n  left: calc(50% - 12px);\\n  width: 24px;\\n  height: 6px;\\n  background: #2b1d14;\\n  border-radius: 0 0 12px 12px;\\n}\\n\\n.mouth-talk.talking {\\n  animation: mouth-talk 0.15s infinite alternate;\\n}\\n\\n@keyframes mouth-talk {\\n  to {\\n    height: 14px;\\n  }\\n}\\n\\n.mouth-bubble {\\n  position: absolute;\\n  top: calc(50% - 100px);\\n  left: calc(50% + 30px);\\n  padding: 6px 10px;\\n  background: #ffffff;\\n  border: 3px solid #4a3426;\\n  border-radius: 10px;\\n  font-size: 14px;\\n  white-space: nowrap;\\n  opacity: 0;\\n  transition: opacity 0.2s;\\n}\\n\\n.mouth-bubble.show {\\n  opacity: 1;\\n}", "js": "// 點身體隨機說一句話，兩秒後收起來\\nconst talkBody = document.querySelector(\'.body\')\\nconst talkMouth = document.querySelector(\'.mouth-talk\')\\nconst talkBubble = document.querySelector(\'.mouth-bubble\')\\nconst talkLines = [\'你好！\', \'肚子餓了\', \'我是合成獸\', \'再點我一下\', \'今天也要寫程式\']\\nlet talkTimer\\ntalkBody.addEventListener(\'click\', () => {\\n  talkBubble.textContent = talkLines[Math.floor(Math.random() * talkLines.length)]\\n  talkBubble.classList.add(\'show\')\\n  talkMouth.classList.add(\'talking\')\\n  clearTimeout(talkTimer)\\n  talkTimer = setTimeout(() => {\\n    talkBubble.classList.remove(\'show\')\\n    talkMouth.classList.remove(\'talking\')\\n  }, 2000)\\n})"}' WHERE name = '會說話的嘴';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '會說話的嘴', 'js', 'mouth', 60, 'mouth.svg', '{"html": "<div class=\\"mouth-talk\\"></div>\\n<div class=\\"mouth-bubble\\"></div>", "css": ".body {\\n  cursor: pointer;\\n}\\n\\n.mouth-talk {\\n  position: absolute;\\n  top: calc(50% + 14px);\\n  left: calc(50% - 12px);\\n  width: 24px;\\n  height: 6px;\\n  background: #2b1d14;\\n  border-radius: 0 0 12px 12px;\\n}\\n\\n.mouth-talk.talking {\\n  animation: mouth-talk 0.15s infinite alternate;\\n}\\n\\n@keyframes mouth-talk {\\n  to {\\n    height: 14px;\\n  }\\n}\\n\\n.mouth-bubble {\\n  position: absolute;\\n  top: calc(50% - 100px);\\n  left: calc(50% + 30px);\\n  padding: 6px 10px;\\n  background: #ffffff;\\n  border: 3px solid #4a3426;\\n  border-radius: 10px;\\n  font-size: 14px;\\n  white-space: nowrap;\\n  opacity: 0;\\n  transition: opacity 0.2s;\\n}\\n\\n.mouth-bubble.show {\\n  opacity: 1;\\n}", "js": "// 點身體隨機說一句話，兩秒後收起來\\nconst talkBody = document.querySelector(\'.body\')\\nconst talkMouth = document.querySelector(\'.mouth-talk\')\\nconst talkBubble = document.querySelector(\'.mouth-bubble\')\\nconst talkLines = [\'你好！\', \'肚子餓了\', \'我是合成獸\', \'再點我一下\', \'今天也要寫程式\']\\nlet talkTimer\\ntalkBody.addEventListener(\'click\', () => {\\n  talkBubble.textContent = talkLines[Math.floor(Math.random() * talkLines.length)]\\n  talkBubble.classList.add(\'show\')\\n  talkMouth.classList.add(\'talking\')\\n  clearTimeout(talkTimer)\\n  talkTimer = setTimeout(() => {\\n    talkBubble.classList.remove(\'show\')\\n    talkMouth.classList.remove(\'talking\')\\n  }, 2000)\\n})"}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '會說話的嘴');

