-- wings：天使翅膀
UPDATE parts SET category = 'html', slot = 'wings', price = 35, starter_code = '{"html": "<div class=\\"wing-angel left\\"><span></span><span></span><span></span></div>\\n<div class=\\"wing-angel right\\"><span></span><span></span><span></span></div>", "css": "/* 三片白色羽毛由長到短往下疊 */\\n.wing-angel {\\n  position: absolute;\\n  top: calc(50% - 50px);\\n  width: 62px;\\n  height: 60px;\\n}\\n\\n.wing-angel.left {\\n  left: calc(50% - 122px);\\n}\\n\\n.wing-angel.right {\\n  left: calc(50% + 60px);\\n  transform: scaleX(-1);\\n}\\n\\n.wing-angel span {\\n  position: absolute;\\n  right: 0;\\n  height: 14px;\\n  background: #ffffff;\\n  border: 3px solid #4a3426;\\n  border-radius: 14px 4px 4px 14px;\\n}\\n\\n.wing-angel span:nth-child(1) {\\n  top: 0;\\n  width: 54px;\\n}\\n\\n.wing-angel span:nth-child(2) {\\n  top: 17px;\\n  width: 44px;\\n}\\n\\n.wing-angel span:nth-child(3) {\\n  top: 34px;\\n  width: 32px;\\n}", "js": ""}' WHERE name = '天使翅膀';
