FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '天使翅膀');

-- wings：蝙蝠翅膀
UPDATE parts SET category = 'css', slot = 'wings', price = 35, starter_code = '{"html": "<div class=\\"wing-bat left\\"></div>\\n<div class=\\"wing-bat right\\"></div>", "css": "/* clip-path 的點從身體那側開始，繞一圈切出下緣的鋸齒 */\\n.wing-bat {\\n  position: absolute;\\n  top: calc(50% - 44px);\\n  width: 72px;\\n  height: 46px;\\n  background: #3b2a3f;\\n  clip-path: polygon(\\n    100% 20%,\\n    35% 0,\\n    0 30%,\\n    12% 100%,\\n    26% 72%,\\n    42% 100%,\\n    56% 72%,\\n    72% 100%,\\n    86% 72%,\\n    100% 82%\\n  );\\n}\\n\\n.wing-bat.left {\\n  left: calc(50% - 130px);\\n}\\n\\n.wing-bat.right {\\n  left: calc(50% + 58px);\\n  transform: scaleX(-1);\\n}", "js": ""}' WHERE name = '蝙蝠翅膀';
