UPDATE parts SET category = 'html', slot = 'wings', price = 35, starter_code = '{"html": "<div class=\\"wing-butterfly left\\">\\n  <span class=\\"wing-butterfly-top\\"></span>\\n  <span class=\\"wing-butterfly-bottom\\"></span>\\n</div>\\n<div class=\\"wing-butterfly right\\">\\n  <span class=\\"wing-butterfly-top\\"></span>\\n  <span class=\\"wing-butterfly-bottom\\"></span>\\n</div>", "css": ".wing-butterfly {\\n  position: absolute;\\n  top: calc(50% - 52px);\\n  width: 56px;\\n  height: 80px;\\n}\\n\\n.wing-butterfly.left {\\n  left: calc(50% - 116px);\\n}\\n\\n.wing-butterfly.right {\\n  left: calc(50% + 60px);\\n  transform: scaleX(-1);\\n}\\n\\n.wing-butterfly span {\\n  position: absolute;\\n  border: 3px solid #4a3426;\\n  border-radius: 50%;\\n}\\n\\n.wing-butterfly-top {\\n  top: 0;\\n  left: 0;\\n  width: 48px;\\n  height: 42px;\\n  background: radial-gradient(circle at 40% 45%, #ffffff 0 6px, transparent 7px), #f2a541;\\n}\\n\\n.wing-butterfly-bottom {\\n  top: 40px;\\n  left: 14px;\\n  width: 34px;\\n  height: 32px;\\n  background: #9b7fd1;\\n}", "js": ""}' WHERE name = '蝴蝶翅膀';
