-- wings：蜻蜓翅膀
UPDATE parts SET category = 'css', slot = 'wings', price = 30, starter_code = '{"html": "<div class=\\"wing-dragonfly left\\"></div>\\n<div class=\\"wing-dragonfly right\\"></div>", "css": "/* 前翅是本體，後翅用 ::after 畫在下面 */\\n.wing-dragonfly,\\n.wing-dragonfly::after {\\n  position: absolute;\\n  height: 14px;\\n  background: rgba(180, 220, 240, 0.6);\\n  border: 2px solid rgba(74, 52, 38, 0.6);\\n  border-radius: 50%;\\n}\\n\\n.wing-dragonfly {\\n  top: calc(50% - 40px);\\n  width: 84px;\\n  transform-origin: right center;\\n  transform: rotate(12deg);\\n}\\n\\n.wing-dragonfly.left {\\n  left: calc(50% - 146px);\\n}\\n\\n.wing-dragonfly.right {\\n  left: calc(50% + 58px);\\n  transform-origin: left center;\\n  transform: rotate(-12deg);\\n}\\n\\n.wing-dragonfly::after {\\n  content: \'\';\\n  top: 18px;\\n  width: 72px;\\n  transform: rotate(-18deg);\\n}\\n\\n.wing-dragonfly.left::after {\\n  right: 0;\\n  transform-origin: right center;\\n}\\n\\n.wing-dragonfly.right::after {\\n  left: 0;\\n  transform-origin: left center;\\n  transform: rotate(18deg);\\n}", "js": ""}' WHERE name = '蜻蜓翅膀';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
