-- wings：龍翼
UPDATE parts SET category = 'css', slot = 'wings', price = 40, starter_code = '{"html": "<div class=\\"wing-dragon left\\"><span></span></div>\\n<div class=\\"wing-dragon right\\"><span></span></div>", "css": "/* clip-path 切掉的地方畫不出邊框，所以外層深色、裡面縮 4px 疊淺色，看起來像有框 */\\n.wing-dragon,\\n.wing-dragon span {\\n  clip-path: polygon(\\n    100% 30%,\\n    60% 0,\\n    0 8%,\\n    16% 42%,\\n    4% 100%,\\n    34% 74%,\\n    50% 100%,\\n    64% 72%,\\n    80% 94%,\\n    100% 70%\\n  );\\n}\\n\\n.wing-dragon {\\n  position: absolute;\\n  top: calc(50% - 64px);\\n  width: 100px;\\n  height: 82px;\\n  background: #4a3426;\\n}\\n\\n.wing-dragon.left {\\n  left: calc(50% - 164px);\\n}\\n\\n.wing-dragon.right {\\n  left: calc(50% + 64px);\\n  transform: scaleX(-1);\\n}\\n\\n.wing-dragon span {\\n  position: absolute;\\n  inset: 4px;\\n  background: #5a9a4a;\\n}", "js": ""}' WHERE name = '龍翼';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
