FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '龍翼');

-- wings：拍拍翅膀
UPDATE parts SET category = 'css', slot = 'wings', price = 45, starter_code = '{"html": "<div class=\\"wing-flap left\\"></div>\\n<div class=\\"wing-flap right\\"></div>", "css": "/* transform-origin 設在靠身體那一側，旋轉起來才像在拍 */\\n.wing-flap {\\n  position: absolute;\\n  top: calc(50% - 40px);\\n  width: 50px;\\n  height: 32px;\\n  background: #85b7eb;\\n  border: 4px solid #4a3426;\\n}\\n\\n.wing-flap.left {\\n  left: calc(50% - 120px);\\n  border-radius: 32px 4px 32px 4px;\\n  transform-origin: right center;\\n  animation: wing-flap-left 0.5s ease-in-out infinite alternate;\\n}\\n\\n.wing-flap.right {\\n  left: calc(50% + 62px);\\n  border-radius: 4px 32px 4px 32px;\\n  transform-origin: left center;\\n  animation: wing-flap-right 0.5s ease-in-out infinite alternate;\\n}\\n\\n@keyframes wing-flap-left {\\n  to {\\n    transform: rotate(25deg);\\n  }\\n}\\n\\n@keyframes wing-flap-right {\\n  to {\\n    transform: rotate(-25deg);\\n  }\\n}", "js": ""}' WHERE name = '拍拍翅膀';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '拍拍翅膀', 'css', 'wings', 45, 'wings.svg', '{"html": "<div class=\\"wing-flap left\\"></div>\\n<div class=\\"wing-flap right\\"></div>", "css": "/* transform-origin 設在靠身體那一側，旋轉起來才像在拍 */\\n.wing-flap {\\n  position: absolute;\\n  top: calc(50% - 40px);\\n  width: 50px;\\n  height: 32px;\\n  background: #85b7eb;\\n  border: 4px solid #4a3426;\\n}\\n\\n.wing-flap.left {\\n  left: calc(50% - 120px);\\n  border-radius: 32px 4px 32px 4px;\\n  transform-origin: right center;\\n  animation: wing-flap-left 0.5s ease-in-out infinite alternate;\\n}\\n\\n.wing-flap.right {\\n  left: calc(50% + 62px);\\n  border-radius: 4px 32px 4px 32px;\\n  transform-origin: left center;\\n  animation: wing-flap-right 0.5s ease-in-out infinite alternate;\\n}\\n\\n@keyframes wing-flap-left {\\n  to {\\n    transform: rotate(25deg);\\n  }\\n}\\n\\n@keyframes wing-flap-right {\\n  to {\\n    transform: rotate(-25deg);\\n  }\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '拍拍翅膀');

-- wings：會飛的翅膀
UPDATE parts SET category = 'js', slot = 'wings', price = 70, starter_code = '{"html": "<div class=\\"wing-fly left\\"></div>\\n<div class=\\"wing-fly right\\"></div>", "css": ".wing-fly {\\n  position: absolute;\\n  top: calc(50% - 40px);\\n  width: 50px;\\n  height: 32px;\\n  background: #f3ead8;\\n  border: 4px solid #4a3426;\\n  cursor: pointer;\\n}\\n\\n.wing-fly.left {\\n  left: calc(50% - 120px);\\n  border-radius: 32px 4px 32px 4px;\\n  transform-origin: right center;\\n}\\n\\n.wing-fly.right {\\n  left: calc(50% + 62px);\\n  border-radius: 4px 32px 4px 32px;\\n  transform-origin: left center;\\n}\\n\\n/* 飛的時候整隻上下飄、翅膀一直拍；JS 只負責加上、拿掉 flying */\\n.body.flying {\\n  animation: wing-float 1.2s ease-in-out infinite alternate;\\n}\\n\\n/* 飛的時候點身體還是要能跳：兩個動畫一起放，跳的時候疊在飄浮上面，跳完繼續飄 */\\n.body.flying.jump {\\n  animation:\\n    wing-float 1.2s ease-in-out infinite alternate,\\n    jump 0.4s ease-out;\\n}\\n\\n.body.flying .wing-fly {\\n  animation: wing-fly 0.3s ease-in-out infinite alternate;\\n}\\n\\n@keyframes wing-float {\\n  to {\\n    translate: 0 -16px;\\n  }\\n}\\n\\n@keyframes wing-fly {\\n  to {\\n    scale: 1 0.6;\\n  }\\n}", "js": "// 點翅膀讓整隻飄起來，再點一下停下來；飄和拍翅膀的動作寫在 CSS 的 .flying\\nconst flyBody = document.querySelector(\'.body\')\\ndocument.querySelectorAll(\'.wing-fly\').forEach((wing) => {\\n  wing.addEventListener(\'click\', (event) => {\\n    // 翅膀長在身體裡，不擋住的話也會觸發身體的點擊\\n    event.stopPropagation()\\n    flyBody.classList.toggle(\'flying\')\\n  })\\n})"}' WHERE name = '會飛的翅膀';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '會飛的翅膀', 'js', 'wings', 70, 'wings.svg', '{"html": "<div class=\\"wing-fly left\\"></div>\\n<div class=\\"wing-fly right\\"></div>", "css": ".wing-fly {\\n  position: absolute;\\n  top: calc(50% - 40px);\\n  width: 50px;\\n  height: 32px;\\n  background: #f3ead8;\\n  border: 4px solid #4a3426;\\n  cursor: pointer;\\n}\\n\\n.wing-fly.left {\\n  left: calc(50% - 120px);\\n  border-radius: 32px 4px 32px 4px;\\n  transform-origin: right center;\\n}\\n\\n.wing-fly.right {\\n  left: calc(50% + 62px);\\n  border-radius: 4px 32px 4px 32px;\\n  transform-origin: left center;\\n}\\n\\n/* 飛的時候整隻上下飄、翅膀一直拍；JS 只負責加上、拿掉 flying */\\n.body.flying {\\n  animation: wing-float 1.2s ease-in-out infinite alternate;\\n}\\n\\n/* 飛的時候點身體還是要能跳：兩個動畫一起放，跳的時候疊在飄浮上面，跳完繼續飄 */\\n.body.flying.jump {\\n  animation:\\n    wing-float 1.2s ease-in-out infinite alternate,\\n    jump 0.4s ease-out;\\n}\\n\\n.body.flying .wing-fly {\\n  animation: wing-fly 0.3s ease-in-out infinite alternate;\\n}\\n\\n@keyframes wing-float {\\n  to {\\n    translate: 0 -16px;\\n  }\\n}\\n\\n@keyframes wing-fly {\\n  to {\\n    scale: 1 0.6;\\n  }\\n}", "js": "// 點翅膀讓整隻飄起來，再點一下停下來；飄和拍翅膀的動作寫在 CSS 的 .flying\\nconst flyBody = document.querySelector(\'.body\')\\ndocument.querySelectorAll(\'.wing-fly\').forEach((wing) => {\\n  wing.addEventListener(\'click\', (event) => {\\n    // 翅膀長在身體裡，不擋住的話也會觸發身體的點擊\\n    event.stopPropagation()\\n    flyBody.classList.toggle(\'flying\')\\n  })\\n})"}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '會飛的翅膀');

-- tail：會擺動的尾巴
UPDATE parts SET category = 'js', slot = 'tail', price = 60, starter_code = '{"html": "<div class=\\"tail\\"></div>", "css": ".tail {\\n  position: absolute;\\n  top: calc(50% + 10px);\\n  left: calc(50% + 64px);\\n  width: 50px;\\n  height: 12px;\\n  background: #4a3426;\\n  transform-origin: left center;\\n  cursor: pointer;\\n}\\n\\n.tail.wag {\\n  animation: wag 0.4s ease-in-out infinite alternate;\\n}\\n\\n@keyframes wag {\\n  from {\\n    transform: rotate(-20deg);\\n  }\\n  to {\\n    transform: rotate(20deg);\\n  }\\n}", "js": "// 點一下尾巴開始擺動，再點一下停下來\\nconst tail = document.querySelector(\\".tail\\");\\ntail.addEventListener(\\"click\\", (event) => {\\n  // 尾巴長在身體裡，不擋住的話也會觸發身體的點擊\\n  event.stopPropagation();\\n  tail.classList.toggle(\\"wag\\");\\n});"}' WHERE name = '會擺動的尾巴';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '會擺動的尾巴', 'js', 'tail', 60, 'tail.svg', '{"html": "<div class=\\"tail\\"></div>", "css": ".tail {\\n  position: absolute;\\n  top: calc(50% + 10px);\\n  left: calc(50% + 64px);\\n  width: 50px;\\n  height: 12px;\\n  background: #4a3426;\\n  transform-origin: left center;\\n  cursor: pointer;\\n}\\n\\n.tail.wag {\\n  animation: wag 0.4s ease-in-out infinite alternate;\\n}\\n\\n@keyframes wag {\\n  from {\\n    transform: rotate(-20deg);\\n  }\\n  to {\\n    transform: rotate(20deg);\\n  }\\n}", "js": "// 點一下尾巴開始擺動，再點一下停下來\\nconst tail = document.querySelector(\\".tail\\");\\ntail.addEventListener(\\"click\\", (event) => {\\n  // 尾巴長在身體裡，不擋住的話也會觸發身體的點擊\\n  event.stopPropagation();\\n  tail.classList.toggle(\\"wag\\");\\n});"}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '會擺動的尾巴');

