-- tail：會長大的尾巴
UPDATE parts SET category = 'js', slot = 'tail', price = 50, starter_code = '{"html": "<div class=\\"tail-grow\\"></div>", "css": ".tail-grow {\\n  position: absolute;\\n  top: calc(50% + 10px);\\n  left: calc(50% + 64px);\\n  width: 30px;\\n  height: 12px;\\n  background: #4a3426;\\n  border-radius: 0 6px 6px 0;\\n  cursor: pointer;\\n  transition: width 0.3s;\\n}", "js": "// 每點一下變長 20px，超過 130px 就變回原本的 30px\\nconst growTail = document.querySelector(\'.tail-grow\')\\nlet growLength = 30\\ngrowTail.addEventListener(\'click\', (event) => {\\n  // 尾巴長在身體裡，不擋住的話也會觸發身體的點擊\\n  event.stopPropagation()\\n  growLength = growLength >= 130 ? 30 : growLength + 20\\n  growTail.style.width = `${growLength}px`\\n})"}' WHERE name = '會長大的尾巴';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '會長大的尾巴', 'js', 'tail', 50, 'tail.svg', '{"html": "<div class=\\"tail-grow\\"></div>", "css": ".tail-grow {\\n  position: absolute;\\n  top: calc(50% + 10px);\\n  left: calc(50% + 64px);\\n  width: 30px;\\n  height: 12px;\\n  background: #4a3426;\\n  border-radius: 0 6px 6px 0;\\n  cursor: pointer;\\n  transition: width 0.3s;\\n}", "js": "// 每點一下變長 20px，超過 130px 就變回原本的 30px\\nconst growTail = document.querySelector(\'.tail-grow\')\\nlet growLength = 30\\ngrowTail.addEventListener(\'click\', (event) => {\\n  // 尾巴長在身體裡，不擋住的話也會觸發身體的點擊\\n  event.stopPropagation()\\n  growLength = growLength >= 130 ? 30 : growLength + 20\\n  growTail.style.width = `${growLength}px`\\n})"}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '會長大的尾巴');

