-- feet：彈簧腳
UPDATE parts SET category = 'css', slot = 'feet', price = 30, starter_code = '{"html": "<div class=\\"feet-spring left\\"></div>\\n<div class=\\"feet-spring right\\"></div>", "css": "/* 斜斜的條紋疊起來像一圈一圈的彈簧，::after 是底下的腳墊 */\\n.feet-spring {\\n  position: absolute;\\n  top: calc(50% + 54px);\\n  width: 16px;\\n  height: 30px;\\n  background: repeating-linear-gradient(\\n    160deg,\\n    transparent 0 3px,\\n    #6f6a64 3px 6px\\n  );\\n}\\n\\n.feet-spring.left {\\n  left: calc(50% - 38px);\\n}\\n\\n.feet-spring.right {\\n  left: calc(50% + 22px);\\n}\\n\\n.feet-spring::after {\\n  content: \'\';\\n  position: absolute;\\n  bottom: -6px;\\n  left: -4px;\\n  width: 24px;\\n  height: 6px;\\n  background: #4a3426;\\n}", "js": ""}' WHERE name = '彈簧腳';
