SELECT '彈簧腳', 'css', 'feet', 30, 'feet.svg', '{"html": "<div class=\\"feet-spring left\\"></div>\\n<div class=\\"feet-spring right\\"></div>", "css": "/* 斜斜的條紋疊起來像一圈一圈的彈簧，::after 是底下的腳墊 */\\n.feet-spring {\\n  position: absolute;\\n  top: calc(50% + 54px);\\n  width: 16px;\\n  height: 30px;\\n  background: repeating-linear-gradient(\\n    160deg,\\n    transparent 0 3px,\\n    #6f6a64 3px 6px\\n  );\\n}\\n\\n.feet-spring.left {\\n  left: calc(50% - 38px);\\n}\\n\\n.feet-spring.right {\\n  left: calc(50% + 22px);\\n}\\n\\n.feet-spring::after {\\n  content: \'\';\\n  position: absolute;\\n  bottom: -6px;\\n  left: -4px;\\n  width: 24px;\\n  height: 6px;\\n  background: #4a3426;\\n}", "js": ""}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '彈簧腳');

-- feet：會走路的腳
UPDATE parts SET category = 'js', slot = 'feet', price = 60, starter_code = '{"html": "<div class=\\"feet-walk left\\"></div>\\n<div class=\\"feet-walk right\\"></div>", "css": ".feet-walk {\\n  position: absolute;\\n  top: calc(50% + 54px);\\n  width: 16px;\\n  height: 22px;\\n  background: #4a3426;\\n  cursor: pointer;\\n}\\n\\n.feet-walk.left {\\n  left: calc(50% - 38px);\\n}\\n\\n.feet-walk.right {\\n  left: calc(50% + 22px);\\n}\\n\\n/* 走路時兩隻腳輪流抬起來，右腳晚半拍；JS 只負責加上、拿掉 walking */\\n.body.walking .feet-walk {\\n  animation: feet-step 0.6s ease-in-out infinite;\\n}\\n\\n.body.walking .feet-walk.right {\\n  animation-delay: 0.3s;\\n}\\n\\n@keyframes feet-step {\\n  50% {\\n    translate: 0 -8px;\\n  }\\n}", "js": "// 點腳開始左右交替踏步，再點一下停下來；踏步的動作寫在 CSS 的 .walking\\nconst walkBody = document.querySelector(\'.body\')\\ndocument.querySelectorAll(\'.feet-walk\').forEach((foot) => {\\n  foot.addEventListener(\'click\', (event) => {\\n    // 腳長在身體裡，不擋住的話也會觸發身體的點擊\\n    event.stopPropagation()\\n    walkBody.classList.toggle(\'walking\')\\n  })\\n})"}' WHERE name = '會走路的腳';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '會走路的腳', 'js', 'feet', 60, 'feet.svg', '{"html": "<div class=\\"feet-walk left\\"></div>\\n<div class=\\"feet-walk right\\"></div>", "css": ".feet-walk {\\n  position: absolute;\\n  top: calc(50% + 54px);\\n  width: 16px;\\n  height: 22px;\\n  background: #4a3426;\\n  cursor: pointer;\\n}\\n\\n.feet-walk.left {\\n  left: calc(50% - 38px);\\n}\\n\\n.feet-walk.right {\\n  left: calc(50% + 22px);\\n}\\n\\n/* 走路時兩隻腳輪流抬起來，右腳晚半拍；JS 只負責加上、拿掉 walking */\\n.body.walking .feet-walk {\\n  animation: feet-step 0.6s ease-in-out infinite;\\n}\\n\\n.body.walking .feet-walk.right {\\n  animation-delay: 0.3s;\\n}\\n\\n@keyframes feet-step {\\n  50% {\\n    translate: 0 -8px;\\n  }\\n}", "js": "// 點腳開始左右交替踏步，再點一下停下來；踏步的動作寫在 CSS 的 .walking\\nconst walkBody = document.querySelector(\'.body\')\\ndocument.querySelectorAll(\'.feet-walk\').forEach((foot) => {\\n  foot.addEventListener(\'click\', (event) => {\\n    // 腳長在身體裡，不擋住的話也會觸發身體的點擊\\n    event.stopPropagation()\\n    walkBody.classList.toggle(\'walking\')\\n  })\\n})"}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '會走路的腳');

