-- accessory：會飄的氣球
UPDATE parts SET category = 'js', slot = 'accessory', price = 60, starter_code = '{"html": "<div class=\\"accessory-balloon\\"></div>", "css": ".accessory-balloon {\\n  position: absolute;\\n  top: calc(50% - 100px);\\n  left: calc(50% + 62px);\\n  width: 30px;\\n  height: 36px;\\n  background: #e0526b;\\n  border: 3px solid #4a3426;\\n  border-radius: 50%;\\n  cursor: pointer;\\n}\\n\\n/* 綁在身體上的線 */\\n.accessory-balloon::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 36px;\\n  left: 14px;\\n  width: 2px;\\n  height: 62px;\\n  background: #4a3426;\\n}\\n\\n/* 飄上去再慢慢回來；JS 只負責加上 rising */\\n.accessory-balloon.rising {\\n  animation: balloon-rise 2.4s ease-in-out;\\n}\\n\\n@keyframes balloon-rise {\\n  30% {\\n    translate: 0 -60px;\\n  }\\n}", "js": "// 點氣球讓它飄上去，再慢慢回到原本的位置；飄的動作寫在 CSS 的 .rising\\nconst balloon = document.querySelector(\'.accessory-balloon\')\\nballoon.addEventListener(\'click\', (event) => {\\n  // 氣球長在身體裡，不擋住的話也會觸發身體的點擊\\n  event.stopPropagation()\\n  balloon.classList.add(\'rising\')\\n})\\n\\n// 動畫播完把 class 拿掉，下次才能再飄\\n// 擋住不往上傳，不然身體收到 animationend 會把自己的 jump 也拿掉\\nballoon.addEventListener(\'animationend\', (event) => {\\n  event.stopPropagation()\\n  balloon.classList.remove(\'rising\')\\n})"}' WHERE name = '會飄的氣球';
INSERT INTO parts (name, category, slot, price, sprite, starter_code)
SELECT '會飄的氣球', 'js', 'accessory', 60, 'accessory.svg', '{"html": "<div class=\\"accessory-balloon\\"></div>", "css": ".accessory-balloon {\\n  position: absolute;\\n  top: calc(50% - 100px);\\n  left: calc(50% + 62px);\\n  width: 30px;\\n  height: 36px;\\n  background: #e0526b;\\n  border: 3px solid #4a3426;\\n  border-radius: 50%;\\n  cursor: pointer;\\n}\\n\\n/* 綁在身體上的線 */\\n.accessory-balloon::after {\\n  content: \'\';\\n  position: absolute;\\n  top: 36px;\\n  left: 14px;\\n  width: 2px;\\n  height: 62px;\\n  background: #4a3426;\\n}\\n\\n/* 飄上去再慢慢回來；JS 只負責加上 rising */\\n.accessory-balloon.rising {\\n  animation: balloon-rise 2.4s ease-in-out;\\n}\\n\\n@keyframes balloon-rise {\\n  30% {\\n    translate: 0 -60px;\\n  }\\n}", "js": "// 點氣球讓它飄上去，再慢慢回到原本的位置；飄的動作寫在 CSS 的 .rising\\nconst balloon = document.querySelector(\'.accessory-balloon\')\\nballoon.addEventListener(\'click\', (event) => {\\n  // 氣球長在身體裡，不擋住的話也會觸發身體的點擊\\n  event.stopPropagation()\\n  balloon.classList.add(\'rising\')\\n})\\n\\n// 動畫播完把 class 拿掉，下次才能再飄\\n// 擋住不往上傳，不然身體收到 animationend 會把自己的 jump 也拿掉\\nballoon.addEventListener(\'animationend\', (event) => {\\n  event.stopPropagation()\\n  balloon.classList.remove(\'rising\')\\n})"}'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM parts WHERE name = '會飄的氣球');

SELECT slot, COUNT(*) AS parts FROM parts GROUP BY slot;
